package com.nexus.access.backend.auth;
import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*; import org.junit.jupiter.api.Test; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import com.nexus.access.backend.user.*;
class AuthenticationServiceTest { @Test void publicRegistrationAlwaysUsesUserRoleAndHash(){UserRepository users=mock(UserRepository.class);when(users.existsByEmailIgnoreCase(anyString())).thenReturn(false);when(users.save(any())).thenAnswer(i->i.getArgument(0));AuthService service=new AuthService(users,new BCryptPasswordEncoder(12),mock(JwtService.class),mock(RefreshTokenService.class));var result=service.register(new RegisterRequest("Ana","Lopez","ANA@EXAMPLE.COM","PasswordSegura123"));var cap=org.mockito.ArgumentCaptor.forClass(User.class);verify(users).save(cap.capture());assertEquals("ana@example.com",result.email());assertEquals("USER",cap.getValue().getRole());assertNotEquals("PasswordSegura123",cap.getValue().getPasswordHash());}}
